import crypto from 'node:crypto'

import { hashSync as hashNativeSync } from './hash.native.mjs'
import { assertHashParams, GET_P2SH_OP_0 } from './utils/assertHash.mjs'
import { parseHashInput } from './utils/input.mjs'
import { fromUint8Super } from './utils/output.mjs'

if (!crypto.webcrypto) throw new Error('Unexpected crypto-browserify or old Node.js crypto')

let supported

/** @deprecated Use async `hash()` */
export function hashSync(type, data, form = 'buffer') {
  assertHashParams(type, form)
  data = parseHashInput(data) // eslint-disable-line no-param-reassign

  if (type === 'hash160') return hashSync('ripemd160', hashSync('sha256', data), form)
  if (type === 'p2sh-hash160') {
    return hashSync('hash160', [GET_P2SH_OP_0(data), hashSync('hash160', data)], form)
  }

  if (!supported) supported = new Set(crypto.getHashes())
  if (!supported.has(type)) return hashNativeSync(type, data, form)

  const state = crypto.createHash(type)
  if (Array.isArray(data)) {
    for (const entry of data) state.update(entry)
  } else {
    state.update(data)
  }

  if (form === 'hex') return state.digest('hex')
  return fromUint8Super(state.digest(), form)
}

export const hash = async (type, data, form) => hashSync(type, data, form)
